'use strict';
const $ = (s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const state={data:null,page:'dashboard',selectedCase:null,filter:'',opportunities:null,opportunityError:'',opportunityRequest:0,opportunityLoading:false,opportunityFilter:'',opportunityStage:'',selectedOpportunityId:null,selectedVersionId:null,showNotice:true,revision:1};
const api=async(path,opts={})=>{const res=await fetch(path,{...opts,credentials:'same-origin',headers:{'Content-Type':'application/json',...opts.headers},body:opts.body===undefined?undefined:JSON.stringify(opts.body)});const data=await res.json().catch(()=>({}));if(!res.ok){if(res.status===401&&typeof showLogin==='function')showLogin();const e=new Error(data.error?.message||`Request failed (${res.status})`);e.status=res.status;e.data=data;throw e;}if(path.endsWith('/validate-submission')){data.blockers=Array.isArray(data.blockers)?data.blockers:[];data.productionBlockers=Array.isArray(data.productionBlockers)?data.productionBlockers:[];if(data.demoSubmissionAllowed===undefined)data.demoSubmissionAllowed=data.valid===true;}return data;};
async function loadOpportunities(){const request=++state.opportunityRequest,user=state.data?.user?.id||'';state.opportunities=null;state.opportunityError='';state.opportunityLoading=true;try{const dataset=await api('/api/v1/salesforce/opportunities');if(request!==state.opportunityRequest||user!==(state.data?.user?.id||''))return false;state.opportunities=dataset;return true;}catch(error){if(request!==state.opportunityRequest||user!==(state.data?.user?.id||''))return false;state.opportunityError=error.message;throw error;}finally{if(request===state.opportunityRequest)state.opportunityLoading=false;}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,c='USD')=>{if(n===null||n===undefined)return '—';try{return new Intl.NumberFormat('en-US',{style:'currency',currency:c,maximumFractionDigits:2}).format(n);}catch{return Number(n).toLocaleString()+' (currency needed)';}};
const pct=n=>n===null||n===undefined?'-':`${Number(n).toFixed(1)}%`;
const date=s=>s?new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'-';
const stamp=s=>s?new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'-';
const statusClass=s=>({Approved:'green',Agreed:'green',Accepted:'green',Resolved:'green',Open:'amber','In Progress':'purple','Pending Approval':'amber','Awaiting Approval':'amber','Retry Scheduled':'amber',Rejected:'red',Failed:'red',Cancelled:'gray',Expired:'gray',Pending:'amber','Pending Finance Approval':'amber',New:'purple',Negotiation:'purple',Closed:'green','Closed Won':'green','Contract & Launch':'purple',Returned:'amber',Draft:'gray','Handoff Pending':'amber'}[s]||'gray');
const badge=s=>`<span class="status ${statusClass(s)}">${esc(s||'Unknown')}</span>`;
const btn=(label,action,cls='secondary',attrs='')=>action==='new-request'?'':state.data?.user?.role==='Client Partner'&&!['refresh','go-page','open-case','select-versions','open-notification','read-notification','read-all-notifications','open-salesforce-opportunities','view-opportunity','close-opportunity-details'].includes(action)?'':`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const caseById=id=>state.data?.cases.find(c=>c.id===id);
const currentCase=()=>caseById(state.selectedCase)||state.data?.cases[0];
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3400);}
async function refresh(){try{state.dirty=false;state.data=await api('/api/v1/bootstrap');if(!state.selectedCase||!state.data.cases.some(c=>c.id===state.selectedCase))state.selectedCase=state.data.cases[0]?.id;render();}catch(e){$('#content').innerHTML=`<div class="card empty">Unable to load application data: ${esc(e.message)}<br><br><button class="btn primary" data-action="refresh">Retry</button></div>`;}}
function setPage(page){const aliases={workspace:'calculator',rates:'administration',governance:'administration',audit:'administration',exceptions:'workflow',integrations:'workflow'};page=aliases[page]||page;if(!['dashboard','cases','renewals','workspace','versions','calculator','approvals','workflow','administration','notifications','salesforce-opportunities'].includes(page))page='dashboard';state.page=page;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));render();window.scrollTo(0,0);}
function setIdentity(){const user=state.data?.user;$('#signed-in-name').textContent=user?.name||'';$('#signed-in-role').textContent=user?.role||'';$('#user-avatar').textContent=(user?.name||'PT').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();}
function render(){if(!state.data)return;setIdentity();$('#task-count').textContent=state.data.tasks.length||'';const unread=(state.data.notifications||[]).filter(n=>!n.readAt).length;$('#notification-count').textContent=unread||'';$('#salesforce-opportunities-entry').hidden=!['Client Partner','Admin'].includes(state.data.user.role);const titles={"dashboard":["PRICING LIFECYCLE","Dashboard"],"cases":["PRICING LIFECYCLE","Pricing Cases"],"renewals":["PRICING LIFECYCLE","Renewals"],"workspace":["PRICING LIFECYCLE","Resource Estimates & Pricing Calculator"],"versions":["PRICING LIFECYCLE","Negotiations & Pricing Versions"],"calculator":["PRICING LIFECYCLE","Pricing Calculator"],"approvals":["PRICING LIFECYCLE","Approvals"],"workflow":["PRICING LIFECYCLE","Workflow Tracker"],"administration":["POLICY & CONFIGURATION","Administration"],"notifications":["PRICING LIFECYCLE","Notifications"],"salesforce-opportunities":["LOCAL OPPORTUNITY DATA","Salesforce Opportunities"]};const t=titles[state.page]||titles.dashboard;$('#crumb').textContent=t[0];$('#page-title').textContent=t[1];const renderers={dashboard,cases:casesPage,renewals:renewalsPage,workspace:workspacePage,versions:versionsPage,calculator:()=>workspacePage(true),approvals:approvalsPage,workflow:workflowPage,administration:administrationPage,notifications:notificationsPage,'salesforce-opportunities':opportunitiesPage};$('#content').innerHTML=renderers[state.page]();bindDynamic();}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h2>${title}</h2><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function kpi(label,value,sub,icon){const marker=icon&&icon!=='?'&&icon!=='-'?`<span class="kpi-icon">${icon}</span>`:'';return `<div class="kpi"><div class="kpi-top"><span>${label}</span>${marker}</div><div class="kpi-value">${value}</div><div class="kpi-sub">${sub}</div></div>`;}
function caseRows(items,emptyMessage='No pricing cases found.'){if(!items.length)return `<tr><td colspan="7" class="empty">${esc(emptyMessage)}</td></tr>`;return items.map(c=>`<tr><td><div class="case-name">${esc(c.opportunityName)}</div><span class="subtext">${esc(c.id)} - ${esc(c.opportunityId)}</span></td><td>${esc(c.account)}</td><td>${esc(c.bu)}</td><td><div class="pill-row">${(c.workTypes||[]).map(x=>`<span class="pill">${esc(x)}</span>`).join('')}</div></td><td>${badge(c.status)}<span class="subtext">${esc(c.stage||'Proposal')} ? ${esc(c.finalOffer?'Final V'+c.finalOffer.number+' '+money(c.finalOffer.price,c.finalOffer.currency):'Current V'+Math.max(0,...c.versions.map(v=>v.number)))}</span></td><td>${esc(c.owner||'Not assigned')}</td><td><button class="link-button" data-action="open-case" data-id="${c.id}">Open </button></td></tr>`).join('');}
function dashboard(){const cs=state.data.cases,open=cs.filter(c=>!['Closed','Closed Won','Cancelled'].includes(c.status)).length,pending=cs.reduce((n,c)=>n+c.versions.reduce((a,v)=>a+(v.status==='Pending Approval'?v.approvals||[]:[]).filter(t=>t.status==='Pending').length,0),0),exc=cs.reduce((n,c)=>n+c.exceptions.filter(e=>e.status==='Open').length,0),handoffs=cs.reduce((n,c)=>n+c.handoffs.filter(h=>h.status==='Accepted').length,0);const byStatus=['New','In Progress','Awaiting Approval','Negotiation','Agreed','Contract & Launch','Closed Won','Closed','Cancelled'].map(s=>({s,n:cs.filter(c=>c.status===s).length}));const recent=state.data.audit.slice(0,5);return `${pageHead('Pricing lifecycle at a glance','A governed view of pricing work, approvals, and downstream handoffs.',btn('+ New pricing request','new-request','primary')+btn('View workflow','cases','secondary'))}<div class="kpi-grid">${kpi('Active cases',open,`${cs.length} total cases`,'?')}${kpi('Pending approvals',pending,'Cases waiting for reviewer action','-')}${kpi('Open exceptions',exc,'Need follow-up from an assigned owner','?')}${kpi('Accepted handoffs',handoffs,'Successfully handed off downstream','?')}</div><div class="grid-2"><div class="card"><div class="card-head"><div><h3>Case lifecycle</h3><p>See how accessible cases are progressing</p></div><span class="status purple">${cs.length} cases</span></div><div class="card-body">${byStatus.map(x=>`<div class="bar-row"><span>${x.s}</span><div class="bar-track"><div class="bar-fill" style="width:${cs.length?Math.max(x.n?8:0,x.n/cs.length*100):0}%"></div></div><span class="bar-count">${x.n}</span></div>`).join('')}</div></div><div class="card"><div class="card-head"><div><h3>Needs attention</h3><p>Decisions and integration steps needing attention</p></div></div><div class="card-body">${state.data.pendingDecisions.filter(d=>d.status==='Pending').slice(0,3).map(d=>`<div class="exception-item"><div class="exception-icon">?</div><div><strong>${esc(d.decision)}</strong><p>Owner: ${esc(d.owner)}</p><button class="link-button" data-action="go-page" data-page="governance">Review decision</button></div></div>`).join('')}<div class="exception-item"><div class="exception-icon">?</div><div><strong>Project Track integration is in demo mode</strong><p>Live connection and authentication are not configured yet.</p><button class="link-button" data-action="go-page" data-page="integrations">View integration status</button></div></div></div></div></div><div class="card"><div class="card-head"><div><h3>Recent pricing cases</h3><p>Cases available to your signed-in account</p></div><button class="link-button" data-action="go-page" data-page="cases">All cases</button></div><div class="table-wrap"><table><thead><tr><th>Opportunity</th><th>Account</th><th>BU</th><th>Work types</th><th>Status</th><th>Owner</th><th></th></tr></thead><tbody>${caseRows(cs.slice(0,5))}</tbody></table></div></div><div class="section-note mt-16">All case names, rates, cost assumptions, and activities shown here are synthetic demonstration data.</div>`;}
const originalDashboard=dashboard;
dashboard=function(){return originalDashboard().replaceAll('<div class="exception-icon">?</div>','');};
function casesPage(){const cs=state.data.cases.filter(c=>state.filter.startsWith('status:')?c.status===state.filter.slice(7):(`${c.opportunityName} ${c.account} ${c.id} ${c.bu}`).toLowerCase().includes(state.filter.toLowerCase()));const emptyMessage=state.data.user.role==='BU SPOC'?'No pricing cases are assigned to this Tech COE yet. Cases appear here after an external Salesforce pricing request is received and its capability is routed to your Tech COE. Ask Pricing Operations or an Administrator to check the intake and Tech COE mapping.':'No pricing cases are available to this identity yet. Cases appear after an external Salesforce pricing request is received and routed to you.';return `${pageHead('Pricing cases','Cases received from the external Salesforce pricing-request workflow and routed to your identity.') }<div class="card"><div class="card-body"><div class="filter-row"><input id="case-search" placeholder="Search opportunity, account, BU." value="${esc(state.filter)}"><select id="case-status"><option value="">All statuses</option>${['New','In Progress','Awaiting Approval','Negotiation','Agreed','Contract & Launch','Closed Won','Closed','Cancelled','Reopened'].map(s=>`<option ${state.filter===`status:${s}`?'selected':''}>${s}</option>`).join('')} </select><span class="muted">${cs.length} visible cases</span></div></div><div class="table-wrap"><table><thead><tr><th>Opportunity / Case</th><th>Account</th><th>BU</th><th>Work types</th><th>Lifecycle</th><th>Owner</th><th>Action</th></tr></thead><tbody>${caseRows(cs,emptyMessage)}</tbody></table></div></div>`;}
function workspacePage(standalone=false){const c=currentCase();if(!c)return standalone?`${pageHead('Pricing Calculator','Review the working calculation and its assumptions.',calculationInfoButton())}<div class="card empty">No cases are available to this identity.</div>`:'<div class="card empty">No cases are available to this identity.</div>';if(c.pricingRuleSet==='WORKBOOK')return workbookWorkspace(c,standalone);const calc=calculateFor(c),caseSelect=`<select id="workspace-case" class="field-select">${state.data.cases.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.id)} - ${esc(x.opportunityName)}</option>`).join('')}</select>`;if(standalone){const full=workspacePage(false),oldHeader=pageHead('Resource Estimates & Pricing Calculator','Edit shared draft resources and review server-calculated pricing.',caseSelect),source=caseDetailsPanel(c);return full.replace(oldHeader,pageHead('Pricing Calculator','Review and update the working calculation for this case.',caseSelect+calculationInfoButton())).replace(source,'').replace('<div class="workspace-layout combined">','<div class="workspace-layout standalone">')+`<details class="source-context salesforce-source-details" open><summary><span><strong>Salesforce source details</strong></span><span class="source-details-toggle" aria-hidden="true"></span></summary>${source}</details>`;}return `${pageHead('Resource Estimates & Pricing Calculator','Edit shared draft resources and review server-calculated pricing.',caseSelect)}<div class="warning-box"><strong>Demo calculation:</strong> ${esc(state.data.ruleNotice)} Live calculations are not production-approved.</div><div class="card mb-16"><div class="card-head"><div><h3>${esc(c.opportunityName)}</h3><p>${esc(c.id)} - ${esc(c.account)} - Opportunity ${esc(c.opportunityId)}</p></div><div class="pill-row">${badge(c.status)}${(c.workTypes||[]).map(x=>`<span class="pill">${esc(x)}</span>`).join('')}</div></div><div class="card-body"><div class="grid-3"><div class="mini-stat"><label>Client budget</label><strong>${money(c.budget,c.currency)}</strong></div><div class="mini-stat"><label>Target margin (demo)</label><strong>${pct(c.targetMarginPct)}</strong></div><div class="mini-stat"><label>Draft revision / last saved</label><strong>#${c.revision}</strong><span class="subtext">${stamp(c.draftSavedAt)}</span></div></div></div></div>${caseDetailsPanel(c)}<div class="workspace-layout combined">${resourcePanel(c)}<section class="calculator-panel" aria-label="Pricing Calculator">${calculatorPanel(c,calc)}<aside class="workspace-side"><div class="card"><div class="card-head"><h3>Saved pricing KPIs</h3>${badge('Demo only')}</div><div class="card-body"><div class="metric-line"><span>Total revenue</span><strong>${money(calc.totalRevenue,c.currency)}</strong></div><div class="metric-line"><span>Total cost ${canSeeCost()?'':'(restricted)'}</span><strong>${canSeeCost()?money(calc.totalCost,c.currency):'Restricted'}</strong></div><div class="metric-line"><span>Contribution margin</span><strong>${pct(calc.contributionMarginPct)}</strong></div><div class="metric-line"><span>Target margin</span><strong>${pct(calc.targetMarginPct)}</strong></div><div class="metric-line"><span>Target pricing gap</span><strong>${money(calc.pricingGap,c.currency)}</strong></div><div class="metric-line"><span>Budget remaining</span><strong>${calc.totalRevenue===null?'-':money(Number(c.budget||0)-calc.totalRevenue,c.currency)}</strong></div></div></div><div class="card"><div class="card-head"><h3>Validation & rate resolution</h3></div><div class="card-body">${calc.lineResults.map((l,i)=>`<div class="exception-item"><div class="exception-icon">${l.rateResolution==='Resolved'?'-':'!'}</div><div><strong>${esc(l.role||`Line ${i+1}`)}</strong><p>${esc([l.rateSource,l.billingBasis,l.formulaStatus,...l.errors].filter(Boolean).join('; ')||'Resolved')}</p>${badge(l.errors.length?'Needs inputs':l.rateResolution)}</div></div>`).join('')||'<div class="empty">Add a resource line to begin.</div>'}</div></div></aside></section></div><div class="grid-2 mt-16"><div class="card"><div class="card-head"><h3>Case comments</h3><span class="muted">${c.comments.length} notes</span></div><div class="card-body">${c.comments.slice(0,5).map(x=>`<div class="timeline-item"><strong>${esc(x.author)}</strong><p>${esc(x.text)}</p><small>${stamp(x.createdAt)}</small></div>`).join('')||'<p class="section-note">No comments yet.</p>'}<div class="field mt-16"><label>Add comment</label><textarea ${state.data.user.role==='Client Partner'?'disabled':''} id="comment-text" placeholder="Add a note for the case team."></textarea></div>${btn('Post comment','add-comment','secondary')}</div></div><div class="card"><div class="card-head"><h3>Next actions</h3></div><div class="card-body"><p class="section-note">Cases arrive from the external Salesforce trigger. Review source context and complete resource estimates. Save Calculation and submit the working draft to create a formal version. Record a new discussion and submit a fresh version for revised offers. The assigned BU Head and Finance reviewers decide in sequence. Mark the approved version agreed, then complete Contract & Launch and Closed Won. Case ownership: <strong>${esc(c.owner||'Not assigned')}</strong>. The next step depends on resolved rates, required assignments, approved policy configuration and workflow state.</p><div class="actions">${btn('View versions','go-page','secondary','data-page="versions"')}${btn('View exceptions','go-page','secondary','data-page="exceptions"')}${btn('Workflow / close case','go-page','primary','data-page="workflow"')}${btn('Cancel case','cancel-case','danger')}</div></div></div></div>`;}
function calculateFor(c){return state.data.calculations?.[c.id]||{lineResults:[],totalRevenue:null,totalCost:null,contributionMarginPct:null,targetMarginPct:c.targetMarginPct,pricingGap:null,exceptions:[{reason:'Calculate the saved draft first.'}]};}
function calculationInfoButton(){return '<button type="button" class="calculation-help" data-action="working-calculation-info" aria-label="Explain the working calculation" title="How the working calculation is calculated"><span aria-hidden="true">i</span><span>Working calculation</span></button>';}
function workingCalculationGuide(c){
 const workbook=c?.pricingRuleSet==='WORKBOOK';
 const steps=workbook?[
  ['Delivery cost','People × months × hours per month × billability × workbook cost per hour. Product or license lines use their entered units, unit cost and revenue.'],
  ['Selling price','Delivery cost ÷ (1 − target contribution margin). The selected workbook role and experience determine the source cost and derived selling rate.'],
  ['Bench loading','Eligible onshore/offshore costs × the configured bench-loading percentage. This is included in the workbook cost basis.'],
  ['Renewal COLA','For renewals, cost including bench loading × the configured COLA gives the additional renewal cost. COLA does not automatically change the selling price.'],
  ['Contribution margin','(Revenue − total cost) ÷ revenue × 100. Missing or unresolved inputs appear in the calculation and submission checks.']
 ]:[
  ['Scheduled hours','Resource count × hours per resource × number of periods.'],
  ['Estimated cost and base selling price','Estimated cost = scheduled hours × cost per hour. Base selling price = scheduled hours × utilization × resolved selling rate.'],
  ['Renewal, discount and offer','Renewal selling price = base selling price × (1 + COLA). The offer applies the draft discount, unless a recorded negotiation offer overrides it.'],
  ['Contribution margin','(Offer − estimated cost) ÷ offer × 100. Compare the result with the target margin and review any unresolved rates or inputs.']
 ];
 return `<div class="calculation-guide"><p class="calculation-guide-intro">A plain-language guide to the fields and results on this Pricing Calculator page.</p><ol>${steps.map(([title,description])=>`<li><strong>${title}</strong><p>${description}</p></li>`).join('')}</ol><div class="calculation-guide-note"><strong>Using the result</strong><p>Update estimate inputs, then select <strong>Calculate Price</strong> to save edits and refresh results. <strong>Save Calculation</strong> records a calculation; <strong>Submit working draft</strong> creates a formal version for approval. These are local demo rules and are not Finance-approved.</p></div></div>`;
}
function canSeeCost(){return state.data.user.costVisible!==false&&state.data.user.role!=='Client Partner'&&(['Finance','CFO','EVP Finance','BU SPOC'].includes(state.data.user.role)||state.data.user.costVisible===true);}
function approvalsPage(){
 const tasks=[];
 for(const c of state.data.cases)for(const v of c.versions)for(const a of (v.status==='Pending Approval'?v.approvals||[]:[]))if(a.status==='Pending'&&state.data.user.role!=='Client Partner')tasks.push({c,v,a});
 const focused=state.selectedVersionId&&state.data.cases.flatMap(c=>c.versions.map(v=>({c,v}))).find(x=>x.v.id===state.selectedVersionId);
 const focusNote=focused?`<div class="warning-box mb-16">Opened from a version-specific notification: <strong>${esc(focused.c.id)} - ${esc(focused.c.opportunityName)} - V${focused.v.number}</strong> (${esc(focused.v.id)}). The highlighted row below is the exact approval version.</div>`:'';
 return `${pageHead('Approval queue','Review pending pricing versions in sequence. Actions follow your assigned role.',btn('View version approval history','go-page','secondary','data-page="versions"'))}${focusNote}<div class="kpi-grid">${kpi('Pending tasks',tasks.length,'Pending steps across your cases','-')}${kpi('Awaiting approval',state.data.cases.filter(c=>c.status==='Awaiting Approval').length,'Cases at the approval stage','?')}${kpi('Rejected versions',state.data.cases.reduce((n,c)=>n+c.versions.filter(v=>v.status==='Rejected').length,0),'Versions returned for rework','?')}${kpi('Current role',esc(state.data.user.role),'Permissions for this role','?')}</div><div class="card"><div class="card-head"><div><h3>Tasks requiring a decision</h3><p>Each task applies to a submitted, immutable pricing version and follows the configured approval sequence.</p></div></div><div class="table-wrap"><table><thead><tr><th>Case / Version</th><th>Opportunity</th><th>Approval step</th><th>Submitted</th><th>Status</th><th>Action</th></tr></thead><tbody>${tasks.map(({c,v,a})=>{const waiting=v.approvals.find(t=>t.step<a.step&&t.status!=='Approved');const assigned=a.role===state.data.user.role||state.data.user.role==='Admin'&&state.data.user.approvalOverride===true;return `<tr data-version-id="${v.id}" class="${state.selectedVersionId===v.id?'notification-target':''}"><td><strong>${esc(c.id)} / V${v.number}</strong><span class="subtext">${esc(v.id)}</span></td><td>${esc(c.opportunityName)}<span class="subtext">${money(v.calculation?.totalRevenue,v.calculation?.currency||c.currency)} - discount ${pct(v.calculation?.discountPct||0)} - CM ${pct(v.calculation?.contributionMarginPct)} - ${esc(v.comments)}</span></td><td>${esc(a.role)} - Step ${a.step}</td><td>${date(v.submittedAt)}</td><td>${badge(a.status)}</td><td>${waiting?`<span class="muted">Waiting for ${esc(waiting.role)} approval</span>`:!assigned?`<span class="muted">Assigned to ${esc(a.role)}</span>`:`<div class="inline-actions"><button class="btn small primary" data-action="approve" data-case="${c.id}" data-version="${v.id}" data-step="${a.step}">Approve</button><button class="btn small secondary" data-action="reject" data-case="${c.id}" data-version="${v.id}" data-step="${a.step}">Reject</button><button class="btn small secondary" data-action="send-back" data-case="${c.id}" data-version="${v.id}" data-step="${a.step}">Send back</button></div>`}</td></tr>`;}).join('')||'<tr><td colspan="6" class="empty">There are no pending approval tasks for your current role. Tasks appear after a pricing case is submitted and routed to an authorized reviewer.</td></tr>'}</tbody></table></div></div><div class="section-note mt-16">Rate approval is separate from pricing-version approval. A user cannot approve their own rate proposal.</div>`;
}
const unstyledApprovalsPage=approvalsPage;
approvalsPage=function(){return unstyledApprovalsPage().replace('<div class="kpi-grid">','<div class="kpi-grid approval-kpis">');};
function ratesPage(){if(state.data.workbookCatalog?.rates)return workbookRatesPage();return `${pageHead('Rate governance','Effective-dated client and standard rates. Proposed rates require Finance approval.',btn('+ Propose new rate','new-rate','primary'))}<div class="grid-2"><div class="card"><div class="card-head"><div><h3>Approved rate records</h3><p>Rate scope and effective dates are evaluated by the backend.</p></div><span class="status green">${state.data.rates.filter(r=>r.status==='Approved').length} approved</span></div><div class="table-wrap"><table><thead><tr><th>Rate</th><th>Scope</th><th>Work type</th><th>Location</th><th>Amount / hr</th><th>Effective dates</th><th>Status</th></tr></thead><tbody>${state.data.rates.map(r=>`<tr><td><strong>${esc(r.role)}</strong><span class="subtext">${esc(r.grade)} - ${esc(r.bu)}</span></td><td>${esc(r.scope)}${r.account?`<span class="subtext">${esc(r.account)}</span>`:''}</td><td>${esc(r.workType)}</td><td>${esc(r.location)}</td><td>${money(r.amount,r.currency)}</td><td>${date(r.startDate)} - ${date(r.endDate)}</td><td>${badge(r.status)}${r.status==='Approved'?btn('Propose update','edit-rate','secondary small',`data-id="${r.id}"`):''}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-head"><div><h3>Rate proposals</h3><p>Finance approval required before reuse.</p></div></div><div class="card-body">${state.data.rateProposals.map(r=>`<div class="exception-item"><div class="exception-icon">?</div><div style="flex:1"><strong>${esc(r.role)} - ${money(r.amount,r.currency)}</strong><p>${esc(r.account)} - ${esc(r.workType)} - ${esc(r.location)}</p><span class="subtext">Proposed by ${esc(state.data.users.find(u=>u.id===r.proposedBy)?.name||r.proposedBy)}</span>${badge(r.status)}${r.status==='Pending Finance Approval'&&['Finance','Admin'].includes(state.data.user.role)?`<div class="mt-16">${btn('Approve rate','approve-rate','primary small',`data-id="${r.id}"`)}</div>`:''}</div></div>`).join('')||'<div class="empty">No rate proposals.</div>'}</div></div></div><div class="warning-box mt-16">Rate scope keys and fallback behavior remain pending business validation. The current seed data is synthetic and effective-dated for demo use.</div>`;}
function exceptionsPage(){const ex=state.data.cases.flatMap(c=>c.exceptions.map(e=>({...e,caseName:c.opportunityName,caseId:c.id})));return `${pageHead('Exception management','Every exception has a type, owner, severity, blocking scope, and resolution trail.')}<div class="kpi-grid">${kpi('Open exceptions',ex.filter(e=>e.status==='Open').length,'Visible to selected identity','?')}${kpi('High severity',ex.filter(e=>e.severity==='High'&&e.status==='Open').length,'Prioritize investigation','!')}${kpi('Resolved',ex.filter(e=>e.status==='Resolved').length,'Resolution notes retained','-')}${kpi('Cases affected',new Set(ex.filter(e=>e.status==='Open').map(e=>e.caseId)).size,'Across accessible cases','?')}</div><div class="card"><div class="card-head"><h3>Exception register</h3></div><div class="table-wrap"><table><thead><tr><th>Exception</th><th>Case</th><th>Severity</th><th>Blocking</th><th>Owner</th><th>Created</th><th>Status</th><th></th></tr></thead><tbody>${ex.map(e=>`<tr><td><strong>${esc(e.type)}</strong><span class="subtext">${esc(e.reason)}</span></td><td>${esc(e.caseId)}<span class="subtext">${esc(e.caseName)}</span></td><td>${badge(e.severity)}</td><td>${e.blocking?'Yes':'No'}</td><td>${esc(state.data.users.find(u=>u.id===e.owner)?.name||e.owner)}</td><td>${date(e.createdAt)}</td><td>${badge(e.status)}</td><td>${e.status==='Open'&&['Admin','Finance','BU SPOC','CFO'].includes(state.data.user.role)?`<button class="link-button" data-action="resolve-exception" data-id="${e.id}">Resolve</button>`:''}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No exceptions have been raised yet. Missing rates appear here after you save/validate a case.</td></tr>'}</tbody></table></div></div>`;}
function versionApprovalDecisions(v){
 return (v.approvals||[]).map(a=>'<div class="version-approval-decision"><strong>'+esc(a.role)+'</strong> '+badge(a.status)+'<span class="subtext">'+esc(a.actor||'Awaiting decision')+'</span>'+(a.at?'<span class="subtext">'+stamp(a.at)+'</span>':'')+(a.reason?'<span class="subtext">'+esc(a.reason)+'</span>':'')+'</div>').join('')||'<span class="muted">Not submitted for approval</span>';
}
function versionsPage(){
 const c=currentCase(),rows=state.data.cases.flatMap(c=>c.versions.slice().sort((a,b)=>a.number-b.number).map(v=>({c,v})));
 return pageHead('Negotiations & Pricing Versions','Every calculation and offer revision retains its own history.',btn('Open calculator','go-page','secondary','data-page="workspace"'))+(c?casePicker()+negotiationPanel(c):'<div class="empty">Create a case to begin negotiations.</div>')+
 '<div class="card"><div class="card-head"><h3>Version timeline and comparison</h3></div><div class="table-wrap"><table><thead><tr><th>Case / version</th><th>Customer / opportunity</th><th>Approval decisions</th><th>Who / when</th><th>Price / change</th><th>Discount / CM%</th><th>Version notes</th><th>Status / links</th><th>Next action</th></tr></thead><tbody>'+rows.map(({c,v})=>{
 const prev=c.versions.find(x=>x.number===v.number-1),price=v.calculation?.totalRevenue;
 return '<tr data-version-id="'+v.id+'" class="'+(state.selectedVersionId===v.id?'notification-target':'')+'"><td>'+esc(c.id)+' / V'+v.number+'<span class="subtext">'+esc(v.id)+'</span></td><td>'+esc(c.account)+'<span class="subtext">'+esc(c.opportunityName)+'</span></td><td class="version-approvals">'+versionApprovalDecisions(v)+'</td><td>'+esc(v.createdBy||v.submittedBy)+'<span class="subtext">'+stamp(v.createdAt||v.submittedAt)+'</span></td><td>'+money(price,v.calculation?.currency||c.currency)+'<span class="subtext">'+(prev?.calculation&&price!=null?'Change: '+money(price-prev.calculation.totalRevenue,v.calculation?.currency||c.currency):'First available priced snapshot')+'</span></td><td>'+pct(v.calculation?.discountPct||0)+' / '+pct(v.calculation?.contributionMarginPct)+'</td><td class="version-notes">'+esc(v.comments||v.rejectionReason||'No notes')+'</td><td>'+badge(v.status)+'<span class="subtext">'+esc(c.closedWonVersionId===v.id?'Final accepted':c.agreedVersionId===v.id?'Accepted':v.number===Math.max(...c.versions.map(x=>x.number))?'Current':'Historical')+' | '+esc(v.calculationId||'Legacy snapshot')+' | '+esc(v.negotiationId||'No linked discussion')+'</span></td><td><div class="actions">'+(v.status==='Draft'?btn('Submit V'+v.number,'submit-selected','primary small','data-case="'+c.id+'" data-version="'+v.id+'"'):'')+(v.status==='Approved'?btn('Mark agreed','mark-agreed','secondary small','data-case="'+c.id+'" data-version="'+v.id+'"'):'')+(!['Closed Won','Cancelled'].includes(c.status)?btn('Restore for revision','restore-version','secondary small','data-case="'+c.id+'" data-version="'+v.id+'"'):'')+'</div></td></tr>';
 }).join('')+' </tbody></table></div>'+(!rows.length?'<div class="empty">Save Calculation, then Submit working draft from the calculator.</div>':'')+'</div>'+(c?costHistory(c)+calculationHistory(c):'');
}

function integrationsPage(){const handoffs=state.data.cases.flatMap(c=>c.handoffs.map(h=>({...h,caseName:c.opportunityName})));return `${pageHead('Integration monitor','Salesforce intake and Project Track handoff adapters are mocked. No live endpoint is connected.',btn('+ Salesforce intake demo','new-request','primary'))}<div class="grid-2"><div class="card"><div class="card-head"><div><h3>Salesforce opportunity adapter</h3><p>System of record for opportunity and sales lifecycle</p></div>${badge('Mock')}</div><div class="card-body"><div class="metric-line"><span>Pricing cases in local store</span><strong>${state.data.cases.length}</strong></div><div class="metric-line"><span>Duplicate intake protection</span><strong>Enabled</strong></div><div class="metric-line"><span>Lifecycle simulator</span><strong>Available</strong></div><p class="section-note">The mock intake stores an opportunity snapshot and returns an existing case for repeated opportunity IDs. Configure the real OAuth/app registration and field mapping after stakeholder approval.</p>${btn('Simulate lifecycle event','simulate-salesforce','secondary')}</div></div><div class="card"><div class="card-head"><div><h3>Project Track adapter</h3><p>Versioned commercial handoff contract</p></div>${badge('Mock receiver')}</div><div class="card-body"><div class="metric-line"><span>Handoffs</span><strong>${handoffs.length}</strong></div><div class="metric-line"><span>Accepted</span><strong>${handoffs.filter(h=>h.status==='Accepted').length}</strong></div><div class="metric-line"><span>Failed / rejected</span><strong>${handoffs.filter(h=>['Failed','Rejected'].includes(h.status)).length}</strong></div><div class="metric-line"><span>Retry limit</span><strong>${state.data.config.retryLimit}</strong></div><p class="section-note">The mock receiver simulates acceptance, validation rejection, transient timeout, retry exhaustion, correlation IDs and idempotency. Handoff acceptance is distinct from Salesforce Closed Won.</p>${btn('Create handoff','create-handoff','primary')}</div></div></div><div class="card mt-16"><div class="card-head"><div><h3>Project Track handoff events</h3><p>Acceptance is only recorded after the mock receiver acknowledges the payload.</p></div><span class="status purple">API schema v1.0</span></div><div class="table-wrap"><table><thead><tr><th>Handoff ID</th><th>Case / Version</th><th>Correlation ID</th><th>Attempts</th><th>Last response</th><th>Status</th><th></th></tr></thead><tbody>${handoffs.map(h=>`<tr><td class="mono">${esc(h.id)}</td><td>${esc(h.caseId)}<span class="subtext">${esc(h.versionId)} - ${esc(h.caseName)}</span></td><td class="mono">${esc(h.correlationId)}</td><td>${h.attempts}</td><td>${esc(h.lastResponse?.message||'Pending')}</td><td>${badge(h.status)}</td><td>${['Failed','Retry Scheduled','Rejected'].includes(h.status)&&state.data.user.role==='Admin'?`<button class="link-button" data-action="retry-handoff" data-id="${h.id}">Replay</button>`:''}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No handoffs yet. Mark an approved version agreed and create a mock handoff to see status tracking.</td></tr>'}</tbody></table></div></div><div class="section-note mt-16">Pending integration decisions include API authentication, final payload mapping, handoff trigger, acknowledgement callback, delivery ownership and returned identifiers.</div>`;}
function governancePage(){const ds=state.data.pendingDecisions;return `${pageHead('Rules & pending decisions','Do not treat unresolved business rules as approved policy.',btn('Save configuration','save-config','primary'))}<div class="warning-box"><strong>Production gate:</strong> Demo mode is enabled and the CM formula is not Finance-approved. Production submissions must remain blocked until critical decisions are resolved.</div><div class="grid-3 mb-16"><div class="mini-stat"><label>Demo mode</label><strong>${state.data.config.demoMode?'Enabled':'Disabled'}</strong></div><div class="mini-stat"><label>Formula approval</label><strong>${state.data.config.formulaApproved?'Approved':'Pending'}</strong></div><div class="mini-stat"><label>Pending decisions</label><strong>${ds.filter(d=>d.status==='Pending').length}</strong></div></div><div class="card mb-16"><div class="card-head"><div><h3>Configurable demo rules</h3><p>Only authorized demo roles can change configuration. Formula approval is reserved for Finance leadership / Admin.</p></div></div><div class="card-body"><div class="form-grid"><div class="field"><label>Target contribution margin (%)</label><input id="cfg-margin" type="number" min="0" max="99" value="${state.data.config.targetMarginPct}"></div><div class="field"><label>Standard rate fallback</label><select id="cfg-fallback"><option value="true" ${state.data.config.fallbackAllowed?'selected':''}>Allowed in demo</option><option value="false" ${!state.data.config.fallbackAllowed?'selected':''}>Disabled</option></select></div><div class="field"><label>Integration retry limit</label><input id="cfg-retry" type="number" min="1" max="10" value="${state.data.config.retryLimit}"></div><div class="field"><label>SLA hours (demo)</label><input id="cfg-sla" type="number" min="1" value="${state.data.config.slaHours}"></div></div><div class="field"><label>Pending version policy (demo only)</label><select id="cfg-pending" ${state.data.user.role==='Admin'?'':'disabled'}><option value="block" ${state.data.config.pendingVersionPolicy==='block'?'selected':''}>Block new submission while a version is pending</option><option value="supersede" ${state.data.config.pendingVersionPolicy==='supersede'?'selected':''}>Supersede pending version and cancel outstanding tasks</option></select><p class="section-note">Production policy is pending business approval.</p></div><div class="field"><label>Finance formula approval</label><select id="cfg-approved" ${['Admin','CFO','EVP Finance'].includes(state.data.user.role)?'':'disabled'}><option value="false" ${!state.data.config.formulaApproved?'selected':''}>Not approved - demo only</option><option value="true" ${state.data.config.formulaApproved?'selected':''}>Approved (demonstration only; do not use as real sign-off)</option></select><p class="section-note">Changing this demo toggle does not constitute actual Finance approval. Use only for workflow demonstration.</p></div></div></div><div class="card"><div class="card-head"><div><h3>Pending business decisions</h3><p>Owner, status, decision and impact register from the build specification.</p></div><span class="status amber">${ds.filter(d=>d.status==='Pending').length} pending</span></div><div class="card-body">${ds.map(d=>`<div class="decision-row"><div><strong>${esc(d.decision)}</strong><small>${esc(d.id)} - ${esc(d.priority)} - Owner: ${esc(d.owner)}</small>${d.decisionValue?`<small>Decision: ${esc(d.decisionValue)}</small>`:''}</div><select data-decision-status="${d.id}"><option ${d.status==='Pending'?'selected':''}>Pending</option><option ${d.status==='Decided'?'selected':''}>Decided</option><option ${d.status==='Deferred'?'selected':''}>Deferred</option></select><input data-decision-value="${d.id}" value="${esc(d.decisionValue)}" placeholder="Decision / notes"><button class="btn small secondary" data-action="save-decision" data-id="${d.id}">Save</button></div>`).join('')}</div></div>`;}
function auditPage(){return `${pageHead('Audit trail','Append-oriented evidence for material workflow, configuration, and integration actions.')}<div class="card"><div class="card-head"><h3>Recent events</h3><span class="muted">${state.data.audit.length} retained in current demo store</span></div><div class="table-wrap"><table><thead><tr><th>Timestamp</th><th>Actor</th><th>Action</th><th>Entity</th><th>Details</th></tr></thead><tbody>${state.data.audit.map(a=>`<tr><td>${stamp(a.createdAt)}</td><td>${esc(a.actor)}</td><td><strong>${esc(a.action)}</strong></td><td>${esc(a.entityType)}<span class="subtext">${esc(a.entityId)}</span></td><td class="mono">${esc(JSON.stringify(a.details||{}))}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No audit events yet. Actions will be recorded here.</td></tr>'}</tbody></table></div></div>`;}
function bindDynamic(){if($('#autosave-draft'))$('#autosave-draft').addEventListener('change',e=>{state.autosave=e.target.checked;if(state.autosave&&state.dirty)queueAutosave();});if($('#case-search'))$('#case-search').addEventListener('input',e=>{state.filter=e.target.value;const pos=e.target.selectionStart;render();const el=$('#case-search');el?.focus();el?.setSelectionRange(pos,pos);});if($('#case-status'))$('#case-status').addEventListener('change',e=>{state.filter=e.target.value?`status:${e.target.value}`:'';render();});$$('[data-line]').forEach(el=>el.addEventListener('input',()=>{const c=currentCase();if(c){c.lines=currentDraftLines();state.dirty=true;state.editGeneration=(state.editGeneration||0)+1;if(state.autosave)queueAutosave();}}));if($('#workspace-case'))$('#workspace-case').addEventListener('change',e=>{state.selectedCase=e.target.value;render();});}
function openModal(title,body,onSubmit,submitLabel='Confirm'){const d=$('#modal');$('#modal-title').textContent=title;$('#modal-body').innerHTML='<div id="modal-error" class="warning-box mb-16" role="alert" hidden></div>'+body;$('#modal-submit').textContent=submitLabel;$('#modal-submit').disabled=false;const form=$('#modal-form');form.onsubmit=async e=>{e.preventDefault();if(e.submitter?.value==='cancel'){d.close();return;}const submit=$('#modal-submit');if(submit.disabled)return;submit.disabled=true;try{await onSubmit();d.close();}catch(err){const error=$('#modal-error');error.textContent=err.message;error.hidden=false;toast(err.message);}finally{submit.disabled=false;}};d.showModal();}
function field(label,name,placeholder='',type='text',value=''){return `<div class="field"><label for="form-${name}">${label}</label><input id="form-${name}" name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(value)}" ${type==='number'?'step="any"':''} ${name==='account'&&state.data?.user?.role==='Client Partner'?'readonly':''}></div>`;}
function selectField(label,name,options,value=''){return `<div class="field"><label for="form-${name}">${label}</label><select id="form-${name}" name="${name}">${options.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;}
function formValues(){const out={};$$('#modal-body [name]').forEach(el=>out[el.name]=el.type==='number'?(el.name==='actualUtilizationPct'&&el.value===''?'':Number(el.value)):el.value);return out;}
function currentDraftLines(){const c=currentCase();if(!c)return[];const lines=JSON.parse(JSON.stringify(c.lines));$$('[data-line]').forEach(el=>{const l=lines[Number(el.dataset.line)];if(!l)return;l[el.dataset.key]=['hoursPerPeriod','utilizationPct','periods','costPerHour','quantity','productQuantity','productUnitCost','productRevenue'].includes(el.dataset.key)?Number(el.value):el.value;});if(c.pricingRuleSet==='WORKBOOK')for(const line of lines){const record=state.data.workbookCatalog?.rates.find(r=>r.key===line.workbookRateKey);if(record){line.role=record.role;line.grade=record.experience;}else {line.role='';line.grade='';}}return lines;}
function queueAutosave(){clearTimeout(state.autosaveTimer);state.autosaveTimer=setTimeout(()=>autosaveDraft().catch(e=>toast(e.message)),900);}
async function autosaveDraft(){
 if(state.saveInFlight){await state.saveInFlight;if(state.dirty&&state.autosave)queueAutosave();return;}
 const c=currentCase();if(!c||!state.dirty||!state.autosave)return;const generation=state.editGeneration||0,identity=state.data?.user?.id||'',caseId=c.id;
 const work=(async()=>{try{const res=await api('/api/v1/cases/'+caseId+'/draft/sections/resource-estimates',{method:'PUT',body:{revision:c.revision,lines:structuredClone(c.lines)}});if((state.data?.user?.id||'')!==identity)return;c.revision=res.revision;c.draftSavedAt=res.savedAt;state.data.calculations[caseId]=res.calculation;if(generation===state.editGeneration)state.dirty=false;toast('Resource draft autosaved at revision '+res.revision+'.');}catch(e){state.autosave=false;toast('Autosave stopped: '+e.message+' Refresh and review before saving.');}finally{state.saveInFlight=null;if(state.dirty&&state.autosave)queueAutosave();}})();state.saveInFlight=work;await work;
}
async function saveDraft(){clearTimeout(state.autosaveTimer);if(state.saveInFlight)await state.saveInFlight;const c=currentCase();if(!c)return;const lines=currentDraftLines();const res=await api(`/api/v1/cases/${c.id}/draft/sections/resource-estimates`,{method:'PUT',body:{revision:c.revision,lines}});toast(`Draft saved at revision ${res.revision}.`);await refresh();}
async function act(action,el){const c=currentCase();if(await pocAction(action,el,c))return;switch(action){case'refresh':await refresh();break;case'go-page':if(el.dataset.case)state.selectedCase=el.dataset.case;setPage(el.dataset.page);break;case'open-case':state.selectedCase=el.dataset.id;setPage('calculator');break;case'new-request':openModal('Request pricing from Salesforce mock',`<p class="section-note">Creates one Price Track case per opportunity ID. Duplicate requests return the existing case.</p><div class="form-grid">${field('Salesforce opportunity ID','opportunityId','SF-OPP-1003')}${field('Opportunity name','opportunityName','Customer modernization')}${field('Account','account','Customer name')}${selectField('Business unit','bu',['TMT1','TMT2','R&M','CPG','HLS-A','HLS-CI','RAI','MMM'],'TMT1')}${field('Client budget (USD)','budget','200000','number','200000')}${selectField('Currency','currency',['USD','INR','GBP','EUR'],'USD')}</div><div class="field"><label>Work types (choose one initial type; add mixed lines in workspace)</label><select name="workType"><option>T&M</option><option>FTE</option><option>Program</option><option>Product</option></select></div>`,async()=>{const v=formValues();const out=await api('/api/v1/pricing-requests',{method:'POST',body:{...v,workTypes:[v.workType],source:'Salesforce mock'}});state.selectedCase=out.case.id;toast(out.duplicate?'Duplicate prevented; existing case opened.':'Pricing request created.');await refresh();setPage('calculator');},'Create case');break;case'add-line':{const cc=currentCase();if(!cc)return;const lines=currentDraftLines();state.dirty=true;lines.push({quantity:1,availability:'Available - sample',id:`NEW-${Date.now()}`,bu:cc.bu||'TMT1',workType:cc.workTypes?.[0]||'T&M',role:'',grade:'G3',location:'India',classification:'Offshore',hoursPerPeriod:160,utilizationPct:100,periods:1,startDate:new Date().toISOString().slice(0,10),endDate:new Date(Date.now()+86400000*180).toISOString().slice(0,10),costPerHour:0,currency:cc.currency||'USD',account:cc.account});cc.lines=lines;cc.revision=cc.revision||1;render();break;}case'remove-line':{const cc=currentCase();state.dirty=true;cc.lines=currentDraftLines().filter((_,i)=>i!==Number(el.dataset.index));render();break;}case'save-draft':await saveDraft();break;case'recalculate':await saveDraft();toast('Backend calculation refreshed.');break;case'validate':{await saveDraft();const out=await api(`/api/v1/cases/${currentCase().id}/validate-submission`,{method:'POST',body:{}});openModal('Submission validation',`${out.demoSubmissionAllowed?'<div class="success-box">Demo submission is ready. No blocking rate/cost exceptions detected.</div>':'<div class="warning-box">Demo submission is not ready. Resolve the blockers below.</div>'}<ul>${out.blockers.map(x=>`<li class="section-note">${esc(x)}</li>`).join('')||'<li class="section-note">No blocking submission checks.</li>'}</ul><p class="section-note">Demo submission: ${out.demoSubmissionAllowed?'Ready':'Not ready'}</p><p class="section-note">Production readiness: ${out.productionReady?'Ready':'Not ready'+(out.productionBlockers.length?' ? '+out.productionBlockers.join(' '):'')}</p>`,async()=>{},'Close');break;}case'add-comment':{const text=$('#comment-text')?.value.trim();if(!text)return toast('Enter a comment first.');await api(`/api/v1/cases/${c.id}/comments`,{method:'POST',body:{text}});toast('Comment posted.');await refresh();setPage('workspace');break;}case'approve':openModal('Approve pricing version',`<p class="section-note">Approve version ${esc(el.dataset.version)} at step ${esc(el.dataset.step)}? This decision is permanently recorded in the audit trail.</p>${field('Decision comments','reason')}`,async()=>{await api(`/api/v1/versions/${el.dataset.version}/approval-tasks/${el.dataset.step}/approve`,{method:'POST',body:formValues()});state.selectedCase=el.dataset.case;toast('Approval recorded. View it in Negotiations & Pricing Versions.');await refresh();},'Approve');break;case'reject':openModal('Reject pricing version',`<p class="section-note">A rejection reason is required and the version will return for rework.</p><div class="field"><label>Reason</label><textarea name="reason" required placeholder="Explain the changes required."></textarea></div>`,async()=>{const v=formValues();if(!v.reason.trim())throw new Error('Rejection reason is required.');await api(`/api/v1/versions/${el.dataset.version}/approval-tasks/${el.dataset.step}/reject`,{method:'POST',body:v});toast('Version rejected and returned for rework.');await refresh();},'Reject version');break;case'new-rate':openModal('Propose a new rate',`<p class="section-note">Proposed rates remain unusable until Finance approves. Proposer cannot approve their own rate.</p><div class="form-grid">${field('Account (blank for standard)','account','Customer name')}${selectField('Business unit','bu',['TMT1','TMT2','R&M','CPG','HLS-A','HLS-CI','RAI','MMM'],'TMT1')}${selectField('Work type','workType',['T&M','FTE','Program','Product'],'FTE')}${field('Role / skill','role','Cloud Engineer')}${field('Grade','grade','G3')}${selectField('Location','location',['India','United States','United Kingdom','Poland'],'India')}${selectField('Currency','currency',['USD','INR','GBP','EUR'],'USD')}${field('Rate per hour','amount','40','number','40')}${field('Effective start','startDate','','date',new Date().toISOString().slice(0,10))}${field('Effective end (optional)','endDate','','date','')}</div>`,async()=>{const v=formValues();await api('/api/v1/rates/proposals',{method:'POST',body:v});toast('Rate proposal submitted to Finance.');await refresh();},'Submit proposal');break;case'approve-rate':openModal('Approve proposed rate',`<p class="section-note">Approve this proposed rate for reuse? Self-approval is blocked by the backend.</p>${field('Approval note (optional)','note','Reviewed against Finance rate card')}`,async()=>{await api(`/api/v1/rates/${el.dataset.id}/approve`,{method:'POST',body:formValues()});toast('Rate approved and added to rate records.');await refresh();},'Approve rate');break;case'resolve-exception':openModal('Resolve exception',`<p class="section-note">Resolution notes are required and will be retained in history.</p><div class="field"><label>Resolution notes</label><textarea name="notes" required placeholder="What was checked and how was it resolved?"></textarea></div>`,async()=>{const v=formValues();await api(`/api/v1/exceptions/${el.dataset.id}/resolve`,{method:'POST',body:v});toast('Exception resolved.');await refresh();},'Resolve');break;case'mark-agreed':openModal('Mark version agreed',`<p class="section-note">Record evidence that this exact approved version was agreed by the customer.</p>${field('Agreement evidence','evidence','Email confirmation / contract reference')}`,async()=>{await api(`/api/v1/cases/${el.dataset.case}/mark-agreed`,{method:'POST',body:{versionId:el.dataset.version,evidence:formValues().evidence}});toast('Version marked agreed.');await refresh();},'Mark agreed');break;case'restore-version':openModal('Restore snapshot to draft',`<div class="warning-box">This copies historical inputs into the current working draft. The old approval is not restored.</div>${field('Reason','reason','Rework based on historical version')}`,async()=>{await api(`/api/v1/cases/${el.dataset.case}/restore-to-draft`,{method:'POST',body:{versionId:el.dataset.version,reason:formValues().reason}});state.selectedCase=el.dataset.case;toast('Snapshot restored as a new working state.');await refresh();setPage('workspace');},'Restore draft');break;case'create-handoff':{const eligible=state.data.cases.flatMap(x=>x.versions.filter(v=>['Approved','Agreed'].includes(v.status)).map(v=>({c:x,v})));if(!eligible.length){toast('No approved/agreed versions available. Complete approvals and mark a version agreed first.');break;}openModal('Create Project Track mock handoff',`<div class="field"><label>Approved / agreed version</label><select name="pair">${eligible.map(x=>`<option value="${x.c.id}|${x.v.id}">${esc(x.c.id)} - V${x.v.number} - ${esc(x.c.opportunityName)} (${x.v.status})</option>`).join('')}</select></div>${selectField('Mock receiver behavior','simulation',['success','timeout','reject'],'success')}<p class="section-note">The mock adapter uses a correlation ID and idempotency key. A handoff is not marked accepted until the receiver response is recorded.</p>`,async()=>{const v=formValues(),[caseId,versionId]=v.pair.split('|');await api('/api/v1/integrations/project-track/handoffs',{method:'POST',body:{caseId,versionId,simulation:v.simulation}});toast('Mock handoff processed.');await refresh();},'Send handoff');break;}case'retry-handoff':openModal('Replay Project Track handoff',`<p class="section-note">Replay uses the same idempotency key and preserves previous attempts.</p>${selectField('Mock receiver behavior','simulation',['success','timeout','reject'],'success')}`,async()=>{await api(`/api/v1/integrations/project-track/handoffs/${el.dataset.id}/retry`,{method:'POST',body:formValues()});toast('Handoff replay attempted.');await refresh();},'Replay');break;case'simulate-salesforce':openModal('Simulate Salesforce lifecycle event',`<div class="field"><label>Case</label><select name="caseId">${state.data.cases.map(x=>`<option value="${x.id}">${esc(x.id)} - ${esc(x.opportunityName)}</option>`).join('')}</select></div>${selectField('Event','event',['OpportunityUpdated','OpportunityLost','OpportunityCancelled'],'OpportunityUpdated')}${field('Reason (if cancelled/lost)','reason','Reason for lifecycle change')}`,async()=>{await api('/api/v1/salesforce/simulate',{method:'POST',body:formValues()});toast('Salesforce mock event recorded.');await refresh();},'Simulate event');break;case'save-config':{const b={targetMarginPct:Number($('#cfg-margin').value),fallbackAllowed:$('#cfg-fallback').value==='true',retryLimit:Number($('#cfg-retry').value),slaHours:Number($('#cfg-sla').value),formulaApproved:$('#cfg-approved').value==='true'};await api('/api/v1/config',{method:'PATCH',body:{...b,...(state.data.user.role==='Admin'?{pendingVersionPolicy:$('#cfg-pending').value}:{})}});toast('Demo configuration saved and audited.');await refresh();break;}case'save-decision':{const id=el.dataset.id;const status=$(`[data-decision-status="${id}"]`).value,decisionValue=$(`[data-decision-value="${id}"]`).value;await api(`/api/v1/pending-decisions/${id}`,{method:'PATCH',body:{status,decisionValue}});toast('Decision register updated.');await refresh();break;}case'cancel-case':openModal('Cancel pricing case',`<p class="section-note">Cancellation preserves all submitted versions and audit history.</p>${field('Reason','reason','Opportunity lost or cancelled')}`,async()=>{await api(`/api/v1/cases/${c.id}/cancel`,{method:'POST',body:formValues()});toast('Case cancelled with reason.');await refresh();},'Cancel case');break;default:break;}}

function resourcePanel(c){if(c.pricingRuleSet==='WORKBOOK')return workbookResourcePanel(c);if(state.data.user.role==='Client Partner')return '<div class="card"><div class="card-head"><h3>Resource Estimates</h3></div><div class="card-body">'+c.lines.map(l=>'<p>'+esc(l.role)+' / '+esc(l.grade)+' | '+esc(l.quantity)+' resources | '+esc(l.location)+'</p>').join('')+'<p class="section-note">Read-only commercial view. Pricing Analyst prepares the working draft.</p></div></div>';
  const fields=[['bu','Business unit','text',['TMT1','TMT2','R&M','CPG','HLS-A','HLS-CI','RAI','MMM']],['workType','Work type','text',['T&M','FTE','Program','Product']],['role','Role / skill'],['grade','Grade'],['location','Location','text',['India','United States','United Kingdom','Poland']],['classification','Delivery classification','text',['Offshore','Onshore']],['quantity','Resource count','number'],['availability','Availability / notes'],['currency','Currency','text',['USD','INR','GBP','EUR']],['hoursPerPeriod','Hours / resource / period','number'],['utilizationPct','Manual utilization (%)','number'],['periods','Duration (periods)','number'],['startDate','Start date','date'],['endDate','End date','date']];
  return '<div class="card resource-panel"><div class="card-head"><div><h3>Resource Estimates</h3><p>Enter assignments, capacity and dates. Save the draft before validating or submitting.</p></div><span class="status purple">'+c.lines.length+' lines</span></div><div class="card-body"><div class="actions">'+btn('+ Add resource','add-line')+btn('Save draft','save-draft','primary')+'<label><input id="autosave-draft" type="checkbox" '+(state.autosave?'checked':'')+'> Autosave resource draft</label>'+(['BU SPOC','Admin'].includes(state.data.user.role)?btn('Validate resource estimates','validate-resources'): '')+'</div><p class="section-note">Open a line to edit it. Changing a resource invalidates validation for the prior draft revision.</p>'+c.lines.map((l,i)=>'<details class="resource-detail" '+(i===0?'open':'')+'><summary><strong>'+esc(l.role||'New resource')+'</strong><span class="subtext">'+esc([l.workType,l.grade,l.location].filter(Boolean).join(' - '))+' - '+esc(l.quantity??1)+' resources - '+esc(l.utilizationPct??'-')+'% utilization</span></summary><div class="resource-fields">'+fields.map(([key,label,type='text',options])=>'<div class="field"><label for="resource-'+i+'-'+key+'">'+label+'</label>'+(options?'<select id="resource-'+i+'-'+key+'" data-line="'+i+'" data-key="'+key+'">'+[...new Set([l[key],...options].filter(x=>x!==undefined&&x!==''))].map(o=>'<option '+(o===l[key]?'selected':'')+'>'+esc(o)+'</option>').join('')+'</select>':'<input id="resource-'+i+'-'+key+'" data-line="'+i+'" data-key="'+key+'" type="'+type+'" value="'+esc(l[key]??'')+'" '+(type==='number'?'step="any"':'')+'>')+'</div>').join('')+'</div><button class="link-button" data-action="remove-line" data-index="'+i+'">Remove resource</button></details>').join('')+(!c.lines.length?'<p class="empty">Add a resource line to begin.</p>':'')+'</div></div>';
}
function calculatorPanel(c,calc){return '<div class="card"><div class="card-head"><div><h3>Pricing Calculator</h3><p>Source workbook roles and experience determine fixed costs; target CM determines selling price.</p></div></div><div class="table-wrap"><table><thead><tr><th>Resource / duration</th><th>Cost / hr</th><th>Rate / hr</th><th>Calculated price</th><th>Estimated cost</th></tr></thead><tbody>'+c.lines.map((l,i)=>{const r=calc.lineResults.find(x=>x.id===l.id);return '<tr><td>'+esc(l.role||'New resource')+'<span class="subtext">'+esc(l.quantity??1)+' resources * '+esc(l.hoursPerPeriod)+' hours * '+esc(l.periods||1)+' periods * '+esc(l.utilizationPct)+'% utilization</span></td><td>'+(canSeeCost()?(c.pricingRuleSet==='WORKBOOK'?money(r?.costPerHour,c.currency):'<input aria-label="Cost per hour for resource '+(i+1)+'" data-line="'+i+'" data-key="costPerHour" type="number" min="0" step="any" value="'+esc(l.costPerHour??'')+'">'):'Restricted')+'</td><td>'+money(r?.resolvedRate,l.currency)+'</td><td>'+money(r?.revenue,l.currency)+'</td><td>'+(canSeeCost()?money(r?.cost,l.currency):'Restricted')+'</td></tr>';}).join('')+(!c.lines.length?'<tr><td colspan="5" class="empty">Add resources to calculate pricing.</td></tr>':'')+'</tbody></table></div><div class="card-body">'+formulaPanel(c,calc)+'<div class="actions">'+btn('Calculate Price','recalculate')+btn('Save Calculation','save-calculation')+btn('Validate submission','validate')+btn('Submit working draft','create-version','primary')+btn('View submitted versions','go-page','secondary','data-page="versions"')+'</div><p class="section-note">Results reflect the last saved draft. Calculate Price saves resource edits and refreshes backend results. Save Calculation stores resource edits and an immutable calculation record. Submit working draft creates an immutable formal version and its approval tasks. Draft saves do not create formal versions.</p></div></div>';}
function renewalsPage(){const rows=(state.data.renewals||[]).filter(r=>!/^Closed/i.test(r.stage)&&!['Closed Won','Cancelled'].includes(r.caseStatus));return pageHead('Renewals','Review starts three calendar months before Salesforce Close Date. Actual utilization needs a report; planned billability comes from estimates.')+'<div class="card"><div class="table-wrap"><table><thead><tr><th>Opportunity / account</th><th>Close / reminder dates</th><th>Budget / BU</th><th>Utilization / cost COLA</th><th>Status</th><th></th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.opportunityName)+'<span class="subtext">'+esc(r.account)+' · '+esc(r.opportunityId)+'</span></td><td>'+date(r.closeDate)+'<span class="subtext">Review from '+date(r.reminderDate)+'<br>Project end '+date(r.projectEndDate)+'</span></td><td>'+money(r.budget,r.currency)+'<span class="subtext">'+esc(r.vertical)+' / '+esc(r.subVertical)+'<br>BU: '+esc(r.bu||'Select child BU')+'</span></td><td>Actual: '+(r.actualUtilizationPct===null?'Evidence required':pct(r.actualUtilizationPct))+'<span class="subtext">Planned: '+(r.plannedBillabilityPct===null?'Estimates needed':pct(r.plannedBillabilityPct))+'<br>Cost COLA: '+pct(r.colaPct)+'</span></td><td>'+badge(r.caseStatus)+'</td><td>'+(r.caseId?btn('Review renewal','open-case','secondary small','data-id="'+r.caseId+'"'):'<span class="muted">Request pricing externally</span>')+'</td></tr>').join('')+'</tbody></table></div>'+(!rows.length?'<div class="empty">No open renewals in your access scope.</div>':'')+'</div>';}


function workflowPage(){return pageHead('Workflow Tracker','Advance stages in order. Approval, agreement and contract evidence are required before Closed Won.')+state.data.cases.map(c=>{
 const latest=c.versions.slice().sort((a,b)=>b.number-a.number)[0],pending=c.versions.find(v=>v.status==='Pending Approval'),task=pending?.approvals.find(a=>a.status==='Pending'),next=POC_STAGES[POC_STAGES.indexOf(c.stage)+1],hours=Math.max(0,Math.floor((Date.now()-new Date(c.stageChangedAt||c.draftSavedAt))/3600000));
 return '<div class="card mb-16"><div class="card-head"><div><h3>'+esc(c.id)+' | '+esc(c.opportunityName)+'</h3><p>'+esc(c.owner)+' | '+esc(c.account)+' | '+hours+' hours in stage</p></div>'+badge(c.status)+'</div><div class="card-body"><div class="pill-row">'+POC_STAGES.map(stage=>'<span class="pill '+(stage===c.stage?'current-stage':'')+'">'+esc(stage)+'</span>').join('')+'</div><p class="section-note">'+(task?'Waiting on '+esc(task.role)+' for V'+pending.number:latest?'Latest V'+latest.number+': '+esc(latest.status):'Supply resources, rates and a saved calculation.')+'</p>'+(c.finalOffer?'<div class="success-box">Closed Won ? final V'+c.finalOffer.number+' | '+money(c.finalOffer.price,c.finalOffer.currency)+' ? all approvals completed</div>':'')+'<div class="actions">'+btn('Open case','open-case','secondary','data-id="'+c.id+'"')+btn('Versions / acceptance','select-versions','secondary','data-case="'+c.id+'"')+(next&&!['Closed Won','Cancelled'].includes(c.status)?btn(next==='Approval'?'Submit a version':'Advance to '+esc(next),next==='Approval'?'select-versions':'advance-stage','primary','data-case="'+c.id+'" data-stage="'+esc(next)+'"'):'')+'</div><details><summary>Stage history / reasons</summary>'+c.workflowHistory.map(h=>'<p class="section-note">'+stamp(h.at)+' | '+esc(h.actor)+' | '+esc(h.from)+' | '+esc(h.to)+' | '+esc(h.reason)+'</p>').join('')+'</details></div></div>';
 }).join('')+(!state.data.cases.length?'<div class="empty">No accessible cases.</div>':'')+'<details class="support-section"><summary>Exceptions</summary>'+exceptionsPage()+'</details><details class="support-section"><summary>Existing mock intake and handoffs</summary>'+integrationsPage()+'</details>';}


function administrationPage(){if(state.data.user.role==='Client Partner')return '<div class="card empty">Internal administration is restricted.</div>';return pageHead('Administration','Manage access, Tech COE routing and versioned approval policy.')+enterpriseAdminPanel()+governancePage()+'<details class="support-section"><summary>Workbook rate reference</summary>'+ratesPage()+'</details><details class="support-section"><summary>Audit trail</summary>'+auditPage()+'</details>';}

const POC_STAGES=['Suspect','Recognition of Need','Evaluation of Options','Resolution of Concerns','Proposal','Negotiation','Approval','Contract & Launch','Closed Won'];
function casePicker(){const c=currentCase();return '<div class="mb-16"><select id="workspace-case" class="field-select">'+state.data.cases.map(x=>'<option value="'+x.id+'" '+(x.id===c?.id?'selected':'')+'>'+esc(x.id)+' | '+esc(x.opportunityName)+'</option>').join('')+'</select></div>';}
function caseForm(c={}){if(c.pricingRuleSet==='WORKBOOK')return workbookCaseForm(c);const accountNote=state.data.user.role==='Client Partner'?'<p class="section-note">Your assigned customer is '+esc(state.data.user.account)+'. New pricing cases must use this customer.</p>':'';return accountNote+ '<div class="form-grid">'+[['Opportunity reference','opportunityId','text'],['Opportunity name','opportunityName','text'],['Customer','account','text'],['Business unit','bu','text'],['Owner','owner','text'],['Region / location','region','text'],['Service / capability','capability','text'],['Delivery model','deliveryModel','text'],['Scope','scope','text'],['Expected start','startDate','date'],['Contract end','contractEndDate','date'],['Duration (months)','durationMonths','number'],['Budget','budget','number'],['Target CM% (demo)','targetMarginPct','number'],['Discount %','discountPct','number'],['Renewal COLA %','colaPct','number'],['Prior scope / SOW','priorScope','text'],['Extra-resource details','extraResourceNotes','text']].map(([label,k,type])=>field(label,k,'',type,c[k]??({account:state.data.user.role==='Client Partner'?state.data.user.account:'',bu:state.data.user.bu||'R&M',owner:state.data.user.name,region:'India',capability:'Data engineering',deliveryModel:'Offshore',startDate:'2026-11-01',contractEndDate:'2027-04-30',durationMonths:6,budget:100000,targetMarginPct:40,discountPct:0,colaPct:0}[k]??''))).join('')+selectField('Opportunity type','opportunityType',['New business','Renewal','Expansion'],c.opportunityType||'New business')+selectField('Currency','currency',['USD','INR','GBP','EUR'],c.currency||'USD')+'</div><p class="section-note">Updating these inputs starts a new draft revision. Existing versions and approvals remain unchanged. Any negotiated offer override is cleared so the new discount can apply.</p>';}
function caseDetailsPanel(c){const source=c.sourceOpportunity||{},fields=c.pricingRuleSet==='WORKBOOK'?[['Opportunity owner',source.owner],['Account',c.account],['Close date',source.closeDate],['Project period',[c.startDate,c.contractEndDate].filter(Boolean).join(' – ')],['Overall budget',money(c.budget,c.currency)],['Vertical / sub-vertical',[source.vertical,source.subVertical].filter(Boolean).join(' / ')],['Business unit',c.bu||'Child BU not selected'],['Sales stage',c.sourceStage],['Pricing path',c.opportunityType],['Capability',c.capability],['Contract billing type','Not supplied; selected per estimate line']]:[['Account',c.account],['Opportunity owner',c.owner],['Sales stage',c.stage],['Pricing path',c.opportunityType],['Region',c.region],['Capability',c.capability],['Delivery model',c.deliveryModel],['Project period',[date(c.startDate),date(c.contractEndDate)].join(' – ')],['Duration',`${c.durationMonths||'—'} months`],['Budget',money(c.budget,c.currency)],['Final accepted version',c.finalOffer?`V${c.finalOffer.number} · ${money(c.finalOffer.price,c.finalOffer.currency)}`:'No final offer']];return `<div class="source-details-content"><dl class="source-detail-grid">${fields.map(([label,value])=>`<div class="source-detail-item"><dt>${esc(label)}</dt><dd>${esc(value||'Not supplied')}</dd></div>`).join('')}</dl><div class="source-scope"><strong>${c.pricingRuleSet==='WORKBOOK'?'Delivery scope':'Scope / service details'}</strong><p>${esc(c.scope||'No delivery scope has been recorded yet.')}</p></div></div>`;}
function formulaPanel(c,calc){if(c.pricingRuleSet==='WORKBOOK')return '';return '<div class="section-note mb-16">Scheduled hours = resource count * hours per resource * periods. Cost = scheduled hours * cost/hour. Base sell = scheduled hours * utilization * resolved rate. Renewal sell = base * (1 + COLA%). Offer = renewal sell * (1 - discount%) or recorded negotiation offer. CM% = (offer - cost) / offer * 100.<br>Base '+money(calc.preColaRevenue,c.currency)+' | COLA '+pct(calc.colaPct||0)+' | adjusted base '+money(calc.baseRevenue,c.currency)+' | discount '+pct(calc.discountPct||0)+' ('+money(calc.discountAmount,c.currency)+') | offered '+money(calc.totalRevenue,c.currency)+'. '+(c.offeredPrice!==undefined?'Recorded negotiation offer overrides the draft discount.':'')+'</div>';}

function negotiationPanel(c){if(state.data.user.role==='Client Partner')return '';return '<div class="card mb-16"><div class="card-head"><h3>'+esc(c.id)+' | '+esc(c.account)+' ? Negotiation discussions</h3>'+btn('Record discussion','new-negotiation','primary small','data-case="'+c.id+'"')+'</div><div class="card-body">'+c.negotiations.map(n=>'<div class="timeline-item"><strong>'+date(n.discussionDate)+' | '+esc(n.createdBy)+' | '+esc(n.outcome)+'</strong><p>Requested '+money(n.requestedPrice,n.currency)+' / offered '+money(n.offeredPrice,n.currency)+' ? discount '+pct(n.discountPct)+' ? CM '+pct(n.contributionMarginPct)+'</p><p>'+esc(n.notes)+' ? Next: '+esc(n.nextAction)+' ? Discussed version: '+esc(n.versionId||'Working draft')+'</p></div>').join('')+(!c.negotiations.length?'<p class="section-note">No discussions recorded. Supply resources/rates, calculate a price, then record the client discussion.</p>':'')+'</div></div>';}

function costHistory(c){return '<div class="card mt-16"><div class="card-head"><h3>Resource cost change history</h3></div><div class="card-body">'+(canSeeCost()?(c.costHistory||[]).map(h=>'<p>'+esc(h.role)+' / '+esc(h.grade)+' | '+money(h.previousCost,h.currency)+' to '+money(h.costPerHour,h.currency)+' per hour | '+esc(h.actor)+' | '+stamp(h.at)+' | Revision '+h.revision+'</p>').join('')||'<p class="empty">No saved cost changes yet. Save draft or Calculate Price after editing costs.</p>':'<p>Restricted</p>')+'</div></div>'; }

function calculationHistory(c){return '<details class="support-section"><summary>Saved calculations ('+c.calculations.length+')</summary>'+c.calculations.map(r=>'<p class="section-note">'+esc(r.id)+' ? revision '+r.revision+' | '+esc(r.createdBy)+' | '+stamp(r.createdAt)+' | '+money(r.calculation.totalRevenue,r.calculation.currency)+' ? CM '+pct(r.calculation.contributionMarginPct)+'</p>').join('')+'</details>';}
async function pocAction(action,el,c){
 const selected=caseById(el.dataset.case)||c;
 switch(action){
 case 'edit-rate':{
 const r=state.data.rates.find(x=>x.id===el.dataset.id);openModal('Propose updated sample rate','<p class="section-note">Finance approval replaces the current record; past version snapshots remain intact. Self-approval is blocked.</p><div class="form-grid">'+[['Account (blank for standard)','account','text'],['Business unit','bu','text'],['Work type','workType','text'],['Skill','role','text'],['Grade','grade','text'],['Location','location','text'],['Rate per hour','amount','number'],['Effective start','startDate','date'],['Effective end','endDate','date']].map(([label,k,type])=>field(label,k,'',type,r[k])).join('')+selectField('Currency','currency',['USD','INR','GBP','EUR'],r.currency)+'</div>',async()=>{await api('/api/v1/rates/proposals',{method:'POST',body:{...formValues(),supersedesId:r.id}});await refresh();toast('Rate update proposed for Finance approval.');},'Propose update');return true;
 }
 case 'new-request':openModal(state.data.user.role==='Client Partner'?'Mock Salesforce - Request Pricing':'Create sample pricing case',caseForm(),async()=>{const v=formValues(),out=await api(state.data.user.role==='Client Partner'?'/api/v1/salesforce/pricing-requests':'/api/v1/pricing-requests',{method:'POST',body:{...v,workTypes:['T&M']}});state.selectedCase=out.case.id;await refresh();setPage('workspace');toast(out.message|| (out.duplicate?'Existing case opened.':'Sample case created.'));},'Create case');return true;
 case 'edit-case':openModal('Pricing and delivery inputs',caseForm(selected),async()=>{await api('/api/v1/cases/'+selected.id+'/details',{method:'PATCH',body:{...formValues(),revision:selected.revision}});await refresh();toast('Pricing inputs saved.');},'Save inputs');return true;
 case 'validate-resources':await saveDraft();openModal('Validate resource estimates',field('Validation notes','reason'),async()=>{await api('/api/v1/cases/'+currentCase().id+'/resource-validation',{method:'POST',body:{...formValues(),revision:currentCase().revision}});await refresh();toast('Resource validation recorded for the current revision.');},'Validate resources');return true;
 case 'save-calculation':await saveDraft();await api('/api/v1/cases/'+currentCase().id+'/calculations',{method:'POST',body:{}});await refresh();toast('Calculation record saved.');return true;
 case 'create-version':if(state.saveInFlight)await state.saveInFlight;if(state.dirty)throw new Error('Save Calculation to include unsaved resource edits first.');openModal('Submit working draft for approval',field('Reason / negotiation notes','comment'),async()=>{const out=await api('/api/v1/cases/'+c.id+'/versions',{method:'POST',body:{...formValues(),revision:c.revision}});await refresh();setPage('versions');toast('V'+out.version.number+' submitted for sequential approval.');},'Submit for approval');return true;
 case 'submit-selected':await api('/api/v1/cases/'+selected.id+'/versions/'+el.dataset.version+'/submit',{method:'POST',body:{}});await refresh();setPage('approvals');toast('Selected version submitted for sequential approval.');return true;
 case 'select-versions':state.selectedCase=selected.id;setPage('versions');return true;
 case 'new-negotiation':openModal('Record client discussion','<div class="form-grid">'+field('Discussion date','discussionDate','','date',new Date().toISOString().slice(0,10))+field('Requested price','requestedPrice','','number',calculateFor(selected).totalRevenue||'')+field('Offered price','offeredPrice','','number',calculateFor(selected).totalRevenue||'')+field('Notes / reason','notes')+field('Outcome','outcome','Counteroffer')+field('Next action','nextAction','Revise and save calculation')+selectField('Discussed version','versionId',['',...selected.versions.map(v=>v.id)],'')+'</div>',async()=>{await api('/api/v1/cases/'+selected.id+'/negotiations',{method:'POST',body:formValues()});state.selectedCase=selected.id;await refresh();toast('Discussion and offered price recorded. Save a calculation and new version for approval.');},'Record discussion');return true;
 case 'send-back':openModal('Send back for changes',field('Required changes','reason'),async()=>{await api('/api/v1/versions/'+el.dataset.version+'/approval-tasks/'+el.dataset.step+'/send-back',{method:'POST',body:formValues()});await refresh();toast('Version returned; prior decisions are retained.');},'Send back');return true;
 case 'advance-stage':openModal('Advance to '+el.dataset.stage,field('Reason / contract or launch evidence','reason'),async()=>{await api('/api/v1/cases/'+selected.id+'/workflow',{method:'POST',body:{stage:el.dataset.stage,...formValues()}});await refresh();toast('Workflow stage updated.');},'Advance stage');return true;
 default:return false;
 }
}

function opportunitiesPage(){
 const dataset=state.opportunities;
 if(state.opportunityError)return `${pageHead('Salesforce Opportunities','Read-only Salesforce synthetic opportunities for your signed-in identity.')}<div class="card empty">Unable to load opportunities: ${esc(state.opportunityError)}<br><br>${btn('Retry loading opportunities','open-salesforce-opportunities','primary')}</div>`;
 if(!dataset)return '<div class="card empty">Load the supplied Salesforce opportunity dataset to begin.</div>';
 if(!dataset.available)return '<div class="card empty">The local Salesforce opportunity workbook is unavailable. Place "Salesforce sythetic data.xlsx" in the project data folder and refresh. No live Salesforce connection is configured.</div>';
 if(!dataset.items.length)return pageHead('Salesforce opportunities','Source data visible to your signed-in identity.')+'<div class="card empty">No opportunities are assigned to '+esc(state.data.user.name)+'. Ask your administrator to check Opportunity Owner values in the synthetic workbook.</div>';
 const stages=[...new Set(dataset.items.map(item=>item.stage).filter(Boolean))].sort();
 const query=(state.opportunityFilter||'').toLowerCase();
 const items=dataset.items.filter(item=>(!state.opportunityStage||item.stage===state.opportunityStage)&&(!query||[item.sourceOpportunityId,item.proposalNumber,item.account,item.opportunityName,item.stage,item.owner,item.vertical,item.subVertical,item.capability].some(value=>String(value||'').toLowerCase().includes(query))));
 const warnings=(dataset.warnings||[]).map(warning=>`<div class="warning-box">${esc(warning)}</div>`).join('');
 const selected=dataset.items.find(item=>item.sourceOpportunityId===state.selectedOpportunityId);
 const details=selected?opportunityDetails(selected):'';
 const body=items.length?items.map(item=>{
  const existing=state.data.cases.find(c=>c.opportunityId===item.sourceOpportunityId);
  return `<tr><td><button class="link-button" data-action="view-opportunity" data-id="${esc(item.sourceOpportunityId)}">${esc(item.opportunityName)}</button><span class="subtext">${esc(item.sourceOpportunityId)} - Proposal ${esc(item.proposalNumber||'-')}</span></td><td>${esc(item.account)}<span class="subtext">Source stage: ${esc(item.stage||'-')}<br>Type: ${esc(item.type)}<br>Close: ${esc(item.closeDate||'missing')}</span></td><td>${item.amount===null?'-':money(item.amount,item.currency||'USD')}<span class="subtext">${esc(item.currency||'Currency not specified')} - ${esc(item.fiscalPeriod||'')}</span></td><td>${esc(item.owner||'-')}<span class="subtext">${esc([item.vertical,item.subVertical,item.capability].filter(Boolean).join(' - ')||'No capability provided')}</span></td><td>${existing?badge(existing.status):'<span class="status gray">No case yet</span>'}</td><td>${existing?btn('Open case','open-case','secondary small',`data-id="${esc(existing.id)}"`):btn('View details','view-opportunity','secondary small',`data-id="${esc(item.sourceOpportunityId)}"`)}</td></tr>`;
 }).join(''):'<tr><td colspan="6" class="empty">No matching opportunities are available for this account and filter.</td></tr>';
 return `${pageHead('Salesforce Opportunities','Read-only Salesforce synthetic opportunities for your signed-in identity. This is synthetic source data, not a live Salesforce connection.',btn('Pricing Cases','go-page','secondary','data-page="cases"'))}<div class="section-note mb-16">Source: ${esc(dataset.sourceFile)} - Worksheet: ${esc(dataset.worksheet||'-')} - ${dataset.visibleCount??dataset.items.length} accessible rows. Select an opportunity name or reference to view its details. Pricing cases appear after an external pricing request is received.</div>${warnings}${details}<div class="card"><div class="card-body"><div class="filter-row"><input id="opportunity-search" aria-label="Search opportunities" placeholder="Search ID, opportunity, customer, stage, owner." value="${esc(state.opportunityFilter)}"><select id="opportunity-stage" aria-label="Filter opportunities by stage"><option value="">All stages</option>${stages.map(stage=>`<option value="${esc(stage)}" ${state.opportunityStage===stage?'selected':''}>${esc(stage)}</option>`).join('')}</select><span class="muted">${items.length} opportunities</span></div></div><div class="table-wrap"><table><thead><tr><th>Opportunity / reference</th><th>Customer / stage</th><th>Amount / period</th><th>Source owner / capability</th><th>Price Track case</th><th></th></tr></thead><tbody>${body}</tbody></table></div></div>`;
}

function opportunityDetails(item){
 const existing=state.data.cases.find(c=>c.opportunityId===item.sourceOpportunityId);
 const fields=[
  ['Opportunity ID',item.sourceOpportunityId],['Proposal number',item.proposalNumber],['Account',item.account],
  ['Opportunity type',item.type],['Sales stage',item.stage],['Owner',item.owner],
  ['Amount',item.amount===null?'-':money(item.amount,item.currency||'USD')],['Fiscal period',item.fiscalPeriod],
  ['Close date',item.closeDate],['Vertical',item.vertical],['Sub-vertical',item.subVertical],
  ['Capability',item.capability],['Project start',item.projectStartDate],['Project end',item.projectEndDate],
  ['Duration (months)',item.durationMonths]
 ];
 const details=fields.filter(([,value])=>value!==undefined&&value!==null&&value!=='').map(([label,value])=>`<tr><th scope="row">${esc(label)}</th><td>${esc(value)}</td></tr>`).join('');
 const caseInfo=existing?`<p>${badge(existing.status)} ${esc(existing.id)}</p>${btn('Open pricing case','open-case','secondary small',`data-id="${esc(existing.id)}"`)}`:'<p><span class="status gray">No case yet</span></p><p class="section-note">This is not a login or opportunity error. No pricing request has reached Price Track for this opportunity yet. Requests are submitted through the external Pricing Intake workflow; the case will appear here after the trigger is received.</p>';
 return `<div class="card mb-16"><div class="card-head"><div><h3>${esc(item.opportunityName)}</h3><p>Read-only source opportunity details</p></div>${btn('Close details','close-opportunity-details','secondary small')}</div><div class="card-body"><div class="table-wrap"><table><tbody>${details}</tbody></table></div><div class="section-note mt-16"><strong>Price Track status</strong>${caseInfo}</div></div></div>`;
}

function notificationsPage(){
 const items=state.data.notifications||[];
 const unread=items.filter(item=>!item.readAt).length;
 const actions=unread?btn('Mark all as read','read-all-notifications','secondary'):'';
 if(!items.length)return `${pageHead('Notifications','In-app alerts for approvals and supported workflow events.',actions)}<div class="card empty">No notifications yet. Approval and workflow notifications appear here when a relevant Price Track event occurs.</div>`;
 return `${pageHead('Notifications',`${items.length} recent notification${items.length===1?'':'s'} - ${unread} unread`,actions)}<div class="notification-list">${items.map(item=>`<article class="notification-item ${item.readAt?'':'unread'}"><div class="notification-main"><div class="notification-heading"><strong>${esc(item.title||'Price Track notification')}</strong>${badge(item.readAt?'Read':'Unread')}</div><p>${esc(item.message||'')}</p><span class="subtext">${esc(item.caseReference||item.caseId||'Workflow')} - ${item.versionNumber?`V${esc(item.versionNumber)}`:''} ${item.approvalTaskId?`- Task ${esc(item.approvalTaskId)}`:''} - ${esc(item.type||'workflow')} - ${esc(item.sourceEvent||'')} - ${stamp(item.createdAt)}</span></div><div class="notification-actions">${btn('Open record','open-notification','secondary small',`data-id="${esc(item.id)}"`)}${!item.readAt?btn('Mark read','read-notification','secondary small',`data-id="${esc(item.id)}"`):''}</div></article>`).join('')}</div>`;
}

const existingCaseForm=caseForm;
caseForm=function(c={}){
 const html=existingCaseForm(c);
 if(c.opportunityType&&!['New business','Renewal','Expansion'].includes(c.opportunityType)){
  const option=`<option value="${esc(c.opportunityType)}" selected>${esc(c.opportunityType)} - Salesforce source</option>`;
  return html.replace('<select id="form-opportunityType" name="opportunityType">',`<select id="form-opportunityType" name="opportunityType">${option}`);
 }
 return html;
};

function openOpportunityRequest(item){
 const type=String(item.type||'').trim();
 const knownType={renewal:'Renewal',expansion:'Expansion','new business':'New business','existing business':'Existing business'};
 const opportunityType=knownType[type.toLowerCase()]||type;
 const prefill={
  opportunityId:item.sourceOpportunityId,opportunityName:item.opportunityName,account:item.account,
  owner:state.data.user.name,bu:state.data.user.bu||'R&M',opportunityType,region:'',
  capability:item.capability||'',deliveryModel:'',scope:'',
  startDate:item.projectStartDate||'',contractEndDate:item.projectEndDate||'',
  durationMonths:item.durationMonths||'',currency:item.currency||'USD',budget:item.amount??'',
  targetMarginPct:40,discountPct:0,colaPct:0
 };
 const sourceNote=`<div class="section-note">Prefilled from ${esc(state.opportunities.sourceFile)}. Source owner: ${esc(item.owner||'not supplied')}; Salesforce stage: ${esc(item.stage||'not supplied')}; classification: ${esc(item.sourceOpportunityType||'not supplied')}. Complete missing region, delivery model, scope, dates, and other required fields before creating the case. This local Excel dataset is not a live Salesforce connection.</div>`;
 openModal(`Request pricing - ${item.sourceOpportunityId}`,sourceNote+caseForm(prefill),async()=>{
  const values=formValues();
  const result=await api('/api/v1/salesforce/pricing-requests',{method:'POST',body:{...values,sourceOpportunityId:item.sourceOpportunityId,workTypes:['T&M']}});
  state.pendingOpportunity=null;state.selectedCase=result.case.id;await refresh();setPage('workspace');
  toast(result.message||(result.duplicate?'Existing case opened.':'Pricing case created from the supplied workbook.'));
 },'Create pricing case');
}

const existingAct=act;
const existingBindDynamic=bindDynamic;
bindDynamic=function(){
 existingBindDynamic();
 if($('#opportunity-search'))$('#opportunity-search').addEventListener('input',event=>{state.opportunityFilter=event.target.value;const pos=event.target.selectionStart;render();const field=$('#opportunity-search');field?.focus();field?.setSelectionRange(pos,pos);});
 if($('#opportunity-stage'))$('#opportunity-stage').addEventListener('change',event=>{state.opportunityStage=event.target.value;render();});
};
act=async function(action,el){
 if(await productAction(action,el))return;
 if(action==='open-salesforce-opportunities'||action==='new-request'){
  if(!await loadOpportunities())return;
  state.opportunityFilter='';state.opportunityStage='';setPage('salesforce-opportunities');return;
 }
 if(action==='view-opportunity'){
  const item=state.opportunities?.items.find(opportunity=>opportunity.sourceOpportunityId===el.dataset.id);
  if(!item)throw new Error('This opportunity is no longer available. Refresh the source dataset and try again.');
  state.selectedOpportunityId=item.sourceOpportunityId;render();return;
 }
 if(action==='close-opportunity-details'){state.selectedOpportunityId=null;render();return;}
 if(action==='open-notification'){
  const opened=await api(`/api/v1/notifications/${encodeURIComponent(el.dataset.id)}/read`,{method:'POST'});
  state.selectedCase=opened.notification.caseId;state.selectedVersionId=opened.notification.versionId;
  await refresh();const page=['renewals','administration','approvals'].includes(opened.notification.route)?opened.notification.route:'versions';setPage(page);
  const target=$$('[data-version-id]').find(row=>row.dataset.versionId===state.selectedVersionId);target?.scrollIntoView?.({block:'center'});return;
 }
 if(action==='read-notification'){await api(`/api/v1/notifications/${encodeURIComponent(el.dataset.id)}/read`,{method:'POST'});await refresh();return;}
 if(action==='read-all-notifications'){await api('/api/v1/notifications/read-all',{method:'POST',body:{}});await refresh();return;}
 return existingAct(action,el);
};

let actionPending=false;
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-page]');if(nav?.classList.contains('nav-item')){setPage(nav.dataset.page);return;}const el=e.target.closest('[data-action]');if(!el||actionPending)return;actionPending=true;const disabled=el.disabled;el.disabled=true;try{await act(el.dataset.action,el);}catch(err){toast(err.message);if(err.status===409)await refresh();}finally{actionPending=false;if(el.isConnected)el.disabled=disabled;}});
$('#nav').addEventListener('click',e=>{const b=e.target.closest('.nav-item');if(b)setPage(b.dataset.page);});
$('#refresh').addEventListener('click',refresh);$('#dismiss-notice').addEventListener('click',()=>{$('.notice-bar').style.display='none';});
function showLogin(){clearTimeout(state.autosaveTimer);state.autosave=false;state.data=null;state.opportunities=null;state.opportunityRequest++;$('.app-shell').hidden=true;$('#login-screen').hidden=false;}
function showWorkspace(){$('#login-screen').hidden=true;$('.app-shell').hidden=false;}
$('#login-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('#login-submit');button.disabled=true;$('#login-error').textContent='';try{await api('/api/v1/auth/login',{method:'POST',body:{username:$('#login-id').value,password:$('#login-password').value}});$('#login-password').value='';state.page='dashboard';state.selectedCase=null;showWorkspace();await refresh();}catch(error){$('#login-error').textContent=error.message;}finally{button.disabled=false;}});
$('#logout').addEventListener('click',async()=>{if(state.saveInFlight)await state.saveInFlight;await api('/api/v1/auth/logout',{method:'POST',body:{}});showLogin();});
(async()=>{const users=null;try{await api('/api/v1/auth/session');showWorkspace();await refresh();}catch{showLogin();}})();
